<?php
declare(strict_types=1);
require_once __DIR__.'/prompt.php';
function aiConfiguration():array{static $cfg=null;if($cfg!==null)return $cfg;$root=dirname(__DIR__,2);$cfg=require $root.'/config.ai.example.php';if(is_file($root.'/config.ai.local.php'))$cfg=array_replace($cfg,require $root.'/config.ai.local.php');if(getenv('EASY3_AI_KEY'))$cfg['key']=getenv('EASY3_AI_KEY');return $cfg;}
function aiStorageAvailable():bool{try{db()->query('SELECT id,job_json,request_json,lease_token FROM ai_generations LIMIT 0');return true;}catch(Throwable){return false;}}
function aiCapability():array{$cfg=aiConfiguration();$storage=aiStorageAvailable();$configured=!empty($cfg['enabled'])&&trim((string)$cfg['key'])!==''&&function_exists('curl_init')&&$storage;return ['enabled'=>(bool)$cfg['enabled'],'configured'=>$configured,'grouped'=>true,'max_operations'=>null,'reason'=>$configured?null:(!$storage?'migration_required':(!function_exists('curl_init')?'curl_required':(empty($cfg['key'])?'key_required':'disabled')))];}
function aiHttp(array $cfg,array $payload,int $timeout):array{
 $url=rtrim((string)$cfg['base_url'],'/').'/chat/completions';$parts=parse_url($url);if(!$parts||($parts['scheme']??'')!=='https'||empty($parts['host'])||isset($parts['user'])||isset($parts['pass'])||isset($parts['query'])||isset($parts['fragment']))return ['http'=>0,'error'=>'configuration','body'=>''];
 $body='';$ch=curl_init($url);$options=[CURLOPT_POST=>true,CURLOPT_USERAGENT=>(string)($cfg['user_agent']??'EASY3/5.0'),CURLOPT_FOLLOWLOCATION=>false,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$cfg['key']],CURLOPT_POSTFIELDS=>j($payload),CURLOPT_TIMEOUT=>$timeout,CURLOPT_CONNECTTIMEOUT=>min(8,$timeout),CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_WRITEFUNCTION=>function($ch,$chunk)use(&$body){if(strlen($body)+strlen($chunk)>2097152)return 0;$body.=$chunk;return strlen($chunk);}];if(!empty($cfg['ca_file']))$options[CURLOPT_CAINFO]=$cfg['ca_file'];curl_setopt_array($ch,$options);$ok=curl_exec($ch);$errno=curl_errno($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return ['http'=>$http,'body'=>$body,'error'=>$ok===false?($errno===28?'timeout':'transport'):null];
}
function aiGateway(array $technical,array $job,?array $cfg=null,?callable $transport=null):array{
 $cfg??=aiConfiguration();$transport??='aiHttp';if(empty($cfg['enabled'])||trim((string)$cfg['key'])==='')fail('AI не подключён. Ручной редактор доступен.',503);if($transport==='aiHttp'&&!function_exists('curl_init'))fail('Включите PHP cURL для AI.',503);
 $models=array_slice(array_values(array_unique(array_filter(array_merge([$cfg['model']],$cfg['fallback_models']??[])))),0,3);$started=microtime(true);$budget=max(8,min(55,(int)$cfg['total_timeout']));$last='unavailable';
 foreach($models as $model){$remaining=$budget-(microtime(true)-$started);if($remaining<4){$last='timeout';break;}$timeout=max(4,min((int)$cfg['attempt_timeout'],(int)floor($remaining)));$response=$transport($cfg,['model'=>$model,'messages'=>aiTechnologyMessages($technical,$job),'temperature'=>(float)$cfg['temperature'],'max_tokens'=>(int)$cfg['max_tokens']],$timeout);$code=(int)$response['http'];
  if($code===403&&str_contains((string)$response['body'],'1010'))fail('AI-сервис ограничил подключение с этого сервера. Обратитесь в поддержку провайдера; готовые части сохранены.',503);if(in_array($code,[401,403],true))fail('Проверьте серверный ключ AI и разрешения модели: провайдер отклонил запрос.',503);if($code===429)fail('Провайдер ограничил частоту. Прогресс сохранён; продолжите позже.',429);if($response['error']){$last=$response['error'];continue;}if($code<200||$code>=300){$last='provider';continue;}
  try{$json=json_decode($response['body'],true,128,JSON_THROW_ON_ERROR);$choice=$json['choices'][0]??[];$reply=$choice['message']['content']??'';if(!is_string($reply)||!trim($reply)||($choice['finish_reason']??'')==='length'){$last='truncated';continue;}$data=($job['stage']==='outline')?aiOutlinePage($reply):aiOperationsPage($reply);}catch(JsonException|AppError){$last='invalid';continue;}
  $usage=[];foreach(['prompt_tokens','completion_tokens','total_tokens'] as $k)$usage[$k]=isset($json['usage'][$k])&&is_numeric($json['usage'][$k])?max(0,(int)$json['usage'][$k]):null;
  return ['data'=>$data,'model'=>$model,'prompt_version'=>AI_TECHNOLOGY_PROMPT_VERSION,'usage'=>$usage,'latency_ms'=>(int)round((microtime(true)-$started)*1000)];
 }
 fail(match($last){'timeout'=>'AI не успел закончить часть. Прогресс сохранён; повторите продолжение.','truncated','invalid'=>'AI не вернул целую корректную часть. Повторите; готовые узлы сохранены.',default=>'AI временно недоступен. Прогресс сохранён.'},502);
}
